use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut jobs = Vec::new();
    for item in data {
        let arrival = item[0].as_i64().unwrap();
        let duration = item[1].as_i64().unwrap();
        jobs.push((arrival, duration));
    }

    let mut total_time = 0;
    let mut current_time = 0;

    for (arrival, duration) in jobs {
        if current_time >= arrival {
            total_time += current_time - arrival;
        }
        current_time += duration;
    }

    Value::from(total_time)
}
